import{z as B,x as d,o as l,c as o,q as t,j as s,D as e,d as r,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"self-rewarding 的循环依赖","description":"","frontmatter":{"title":"self-rewarding 的循环依赖","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-reward-debate.md","filePath":"llm/self-reward-debate.md","lastUpdated":1791063341000}'),D={name:"llm/self-reward-debate.md"};function m(p,E,f,F,h,u){const A=d("Mermaid");return l(),o("div",null,[E[2]||(E[2]=t('<h1 id="self-rewarding-的循环依赖" tabindex="-1">self-rewarding 的循环依赖 <a class="header-anchor" href="#self-rewarding-的循环依赖" aria-label="Permalink to &quot;self-rewarding 的循环依赖&quot;">​</a></h1><div class="epigraph"><p>奖励出自被训练的同一个模型，优化目标就在每一轮被改写成它此刻的口味；循环把测量误差泵成分布偏移。</p><footer>—— Yuan 等, Self-Rewarding Language Models（2024）；Panickssery 等, LLM Evaluators Recognize and Favor Their Own Generations（2024）</footer></div><p><a href="/llm/synthetic-curriculum-close">上一课</a>把自出题-自排课接进闭环：难度分布受控的合成课程让验证器有题可验，代价是出题人对「学什么」的理解会漂移。缺口再退一步：若奖励本身也出自同一个模型——self-rewarding 让模型给自己的输出打分、构造成对偏好、再用偏好损失更新自己，裁判与选手合一。<a href="/llm/llm-judge-bias">裁判偏差</a>在一次性评测里只是让名次可疑；进了训练环，偏差成为梯度本身，被逐轮放大。<a href="/llm/self-play-lm">自博弈</a>已经预警：没有判定器的互评会退化成自奖励。本课写这条循环依赖的形状，以及哪里必须放外生锚点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Yuan 等人 2024 年把迭代写成三步：当前模型对每个提示生成多个回答；同一模型按裁判脚本打分、两两比较构偏好对；用 DPO 在自产偏好上更新，回到第一步。三轮之内 AlpacaEval 胜率持续上升。结果诱人，也因诱人而危险：整个回路里没有任何一个数来自模型之外。位置偏差、长度偏差、同族偏好——在评测里是方差，在这里是系统性增量：策略梯度精确地沿「裁判喜欢什么」的方向走，而裁判的口味就是模型自己的口味。不这么做会错在哪：把这条上升曲线当能力曲线，闭环会安静地把模型推向它自己最顺眼的分布，没有任何报警。</p><p><span class="marginnote">「循环把测量误差泵成分布偏移」翻译一下：裁判打分本有随机误差，评测里平均后可互相抵消；一旦误差方向偏爱模型自己的风格，DPO 每轮专挑这些样本训练，误差就从噪声变成确定的推动力——像天平有小毛病却天天用它称货进货，仓库库存会朝一个方向持续偏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把裁判写成 \\(\\hat R(y;x)=R^*(y;x)+b(y)\\)：\\(R^*\\) 是理想真值，\\(b\\) 是偏差项。人当裁判时，\\(b\\) 与被评模型无关，平均是噪声；裁判与生成器同分布时，自我偏好使 \\(\\mathbb{E}_{y\\sim\\pi_\\theta}[b(y)]\\gt 0\\) 恒成立——模型给自己的输出系统性加分。策略更新最大化 \\(\\mathbb{E}_{y\\sim\\pi_\\theta}[\\hat R]\\)，于是每轮迭代同时抬高 \\(\\mathbb{E}[b]\\)：偏置不是被平均掉，而是被选出来。缓解按强度排：换序与长度控制治位置与冗长，治不了自我偏好；跨族裁判集成稀释同族口味；唯一硬的锚是可验证子信号——把 <a href="/llm/rlvr">RLVR</a> 的程序真值混进奖励，让不可验证维度只占少数票，并保留一个不经过裁判的 held-out 做审计。</p><p><span class="marginnote">数字实例：设两个回答真值打平，模型自己的回答带 +0.3 分的自我偏好，他人回答 0 分。单轮看只是 0.3 的小误差；迭代三轮，策略被推着产出更多这种回答，奖励被偏差越叠越高——这就是「偏差项期望恒为正、且被逐轮选出」的直观含义。</span></p>',9)),(l(),s(n,null,{default:e(()=>[i(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E5%BD%93%E5%89%8D%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%E5%80%99%E9%80%89%22%5D%20--%3E%20JUDGE%5B%22%E5%90%8C%E4%B8%80%E6%A8%A1%E5%9E%8B%E5%BD%93%E8%A3%81%E5%88%A4%E6%89%93%E5%88%86%22%5D%0A%20%20JUDGE%20--%3E%20PAIR%5B%22%E6%9E%84%E9%80%A0%E5%81%8F%E5%A5%BD%E5%AF%B9%22%5D%0A%20%20PAIR%20--%3E%20DPO%5B%22DPO%20%E6%9B%B4%E6%96%B0%E7%AD%96%E7%95%A5%22%5D%0A%20%20DPO%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%EF%BC%9A%E6%9B%B4%E6%96%B0%E5%90%8E%E7%9A%84%E6%A8%A1%E5%9E%8B%E5%8D%B3%E6%96%B0%E8%A3%81%E5%88%A4%22%5D%0A%20%20NEXT%20--%3E%20GEN%0A%20%20ANCHOR%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E5%AD%90%E4%BF%A1%E5%8F%B7%E4%B8%8E%E5%A4%96%E7%94%9F%20held-out%22%5D%20-.-%3E%7C%22%E5%A4%96%E7%94%9F%E9%94%9A%EF%BC%8C%E4%B8%8D%E8%BF%9B%E5%BE%AA%E7%8E%AF%22%7C%20PAIR%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"Panickssery 等人把自我偏好的机制钉死：把法官自己的输出换成等质量的他人输出，胜率显著下降；法官甚至在内容不变时认出「这是我的写法」。偏好来自风格重叠——同族模型的 n-gram 与句式更像裁判的预训练——而 DPO 把风格差距直接写成对数概率差。所以循环的不动点不是「最好的回答」，而是「模型最顺眼的回答」：早期增益来自格式与详略（裁判爱列表、爱长文），后期停滞，因为口味已经是它自己。测量侧的随机误差，经选择压力变成了生成侧的固定偏移——这是循环依赖与「用一次法官打分」的本质区别。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"Yuan 等报告的三轮增益与回答长度增长同步，且没有外生验证环节；Panickssery 等进一步显示自我偏好在质量打平时仍然存在。两者相加：不设外生读数，无法把「更像自己」与「更好」分开。")],-1)),E[6]||(E[6]=a("p",null,"同一条偏差，为什么在评测里只是可疑、进训练环就致命：",-1)),(l(),s(n,null,{default:e(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%90%8C%E4%B8%80%E5%81%8F%E5%B7%AE%EF%BC%9A%E4%BD%8D%E7%BD%AE%20%2F%20%E9%95%BF%E5%BA%A6%20%2F%20%E5%90%8C%E6%97%8F%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20EV%5B%22%E5%8F%AA%E7%94%A8%E4%B8%80%E6%AC%A1%EF%BC%9A%E8%AF%84%E6%B5%8B%E6%89%93%E5%88%86%22%5D%0A%20%20B%20--%3E%20TR%5B%22%E8%BF%9B%E8%AE%AD%E7%BB%83%E7%8E%AF%EF%BC%9A%E5%81%8F%E5%B7%AE%E6%88%90%E4%B8%BA%E6%A2%AF%E5%BA%A6%E6%9C%AC%E8%BA%AB%22%5D%0A%20%20EV%20--%3E%20N1%5B%22%E5%90%8E%E6%9E%9C%EF%BC%9A%E5%90%8D%E6%AC%A1%E5%8F%AF%E7%96%91%EF%BC%8C%E6%8D%A2%E5%BA%8F%E5%8F%AF%E7%BC%93%E8%A7%A3%22%5D%0A%20%20TR%20--%3E%20N2%5B%22%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%E6%B2%BF%E3%80%8C%E8%A3%81%E5%88%A4%E5%96%9C%E6%AC%A2%E4%BB%80%E4%B9%88%E3%80%8D%E8%B5%B0%22%5D%0A%20%20N2%20--%3E%20FP%5B%22%E9%80%90%E8%BD%AE%E6%94%BE%E5%A4%A7%EF%BC%8C%E4%B8%8D%E5%8A%A8%E7%82%B9%E6%98%AF%E3%80%8C%E6%9C%80%E9%A1%BA%E7%9C%BC%E3%80%8D%E8%80%8C%E9%9D%9E%E3%80%8C%E6%9C%80%E5%A5%BD%E3%80%8D%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">直觉类比：辩论是把「自查」换成「对质」——考生不能当自己的考官，两个考生互相挑错，最后由人类打分。但长论证超出人类注意力时，实际裁决又退回模型互评，循环依赖就绕回来了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>self-rewarding 不是全错：若有大量可验证样本锚住真值维度，剩余开放维度用自评，增益可能真实存在。辩论是另一条出路——Irving 等 2018 年的设计里裁决权在人，两个模型互相攻诘，裁判不再是选手；但它依赖链的忠实性，人类注意力成为新瓶颈，且胜负判据本身仍常退化为模型互评。凡是宣称「全自监督后训练提升了开放能力」的报告，第一问都该是：裁判是谁，换序了吗，有没有一个不经过裁判的 held-out。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>裁判与选手同模型时，自我偏好使偏差项恒正，循环把偏置逐轮选出来。</li><li>换序与长度控制必要但不充分，治不了自我偏好。</li><li>可验证子信号是唯一硬锚；开放维度自评必须配外生 held-out。</li><li>增益曲线先拆长度与格式，再谈能力。</li><li>出处：Yuan 等 Self-Rewarding Language Models（2024）；Panickssery 等（2024）；Irving 等 AI Safety via Debate（2018）；偏差清单见 <a href="/llm/llm-judge-bias">LLM 裁判偏差</a>。</li></ul>',5))])}const g=B(D,[["render",m]]);export{b as __pageData,g as default};
